 @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select e from ServiceInstanceEntity e where e.id=:id") Optional<ServiceInstanceEntity> lockById(@org.springframework.data.repository.query.Param("id") UUID id);
